  it('error still propagates after onError hook', async () => {
    const hooks: OrchestratorHooks = {
      onError: async () => {},
    };

    const orchestrator = createChatOrchestrator(createErrorProvider(new Error('boom')), promptBuilder, undefined, {
      hooks,
    });
    await expect(orchestrator.processMessage(createSession('hello'))).rejects.toThrow('boom');
  });

  it('coerces non-Error rejections to Error for onError hook', async () => {
    let receivedError: Error | undefined;
    const hooks: OrchestratorHooks = {
      onError: async (_session, error) => {
        receivedError = error;
      },
    };

    const orchestrator = createChatOrchestrator(
      {
        // eslint-disable-next-line require-yield
        async *sendMessage(): AsyncGenerator<MessageChunk> {
          throw 'string boom';
        },
        async generateStructured<T>(): Promise<T> {
          return {} as T;
        },
      },
      promptBuilder,
      undefined,
      {hooks}
    );

    await expect(orchestrator.processMessage(createSession('hello'))).rejects.toBe('string boom');
    expect(receivedError).toBeInstanceOf(Error);
    expect(receivedError?.message).toBe('string boom');
    expect(receivedError?.cause).toBe('string boom');
  });

  it('coerces undefined rejection to Error for onError hook', async () => {
    let receivedError: Error | undefined;
    const hooks: OrchestratorHooks = {
      onError: async (_session, error) => {
        receivedError = error;
      },
    };

    const orchestrator = createChatOrchestrator(
      {
        // eslint-disable-next-line require-yield
        async *sendMessage(): AsyncGenerator<MessageChunk> {
          throw undefined;
        },
        async generateStructured<T>(): Promise<T> {
          return {} as T;
        },
      },
      promptBuilder,
      undefined,
      {hooks}
    );

    await expect(orchestrator.processMessage(createSession('hello'))).rejects.toBeUndefined();
    expect(receivedError).toBeInstanceOf(Error);
    expect(receivedError?.message).toBe('undefined');
    expect(receivedError?.cause).toBeUndefined();
  });
});

